# Wait for the Brain sync job and its thread summaries, at most about five minutes.
import time

from semoss import Insight


def run(scope):
    job = None
    for _ in range(30):
        time.sleep(10)
        job = Insight().run_pixel('BrainGetJob(kind=["sync"]);', raw=False)
        if not isinstance(job, dict):
            break
        if job.get("status") != "running" and not job.get("insightsPending"):
            break
    return job if isinstance(job, dict) else {"status": "unknown"}

