"""Render the daily brief from prepared records and isolated meeting notes."""
import datetime
import html
import re
from urllib.parse import urlsplit


def _text(value):
    if not isinstance(value, str):
        return ""
    value = re.sub(r"[\x00-\x1f\x7f]", " ", value)
    value = " ".join(value.split())
    value = html.escape(value, quote=False)
    return re.sub(r"([\\`*_{}\[\]()#+\-.!|~])", r"\\\1", value)


def _link(label, url):
    label = _text(label)
    if not isinstance(url, str) or len(url) > 8192 or any(
            c.isspace() or ord(c) < 32 or ord(c) == 127 or c in '<>"\\' for c in url):
        return label
    try:
        parsed = urlsplit(url)
        valid = parsed.scheme.lower() in ("http", "https") and bool(parsed.hostname)
        parsed.port  # Reject malformed ports as well as malformed IPv6 addresses.
    except ValueError:
        valid = False
    # Markdown removes these escapes; the destination keeps the source URL's encoding.
    destination = url.replace("(", "\\(").replace(")", "\\)")
    return "[" + label + "](" + destination + ")" if valid else label


def _bounded(value, limit, words, allow_empty=False):
    return (isinstance(value, str) and (allow_empty or bool(value.strip()))
            and len(value) <= limit and len(value.split()) <= words)


def _integer(value):
    # Java's untyped JSON boundary can return an integer as 1.0.
    if type(value) is int:
        return value
    if type(value) is float and value.is_integer():
        return int(value)
    return None


def _meeting_notes(raw, count):
    notes = {}
    rows = raw.get("results") if isinstance(raw, dict) else None
    for row in rows if isinstance(rows, list) else []:
        if not isinstance(row, dict):
            continue
        index = _integer(row.get("index"))
        if index is None or not 0 <= index < count or index in notes:
            continue
        outputs = row.get("outputs")
        note = outputs.get("note") if isinstance(outputs, dict) else None
        notes[index] = note if isinstance(note, dict) and note.get("available") is True else None
    return notes


def _priority_key(item):
    priority = item.get("priority")
    rank = int(priority[1:]) if isinstance(priority, str) and re.fullmatch(r"P\d+", priority) else 99
    return ({"today": 0, "soon": 1, "flexible": 2}.get(item.get("group"), 2),
            item.get("dueDate") or "9999-12-31", rank)


def _title(item, fallback):
    return item.get("title") or item.get("subject") or fallback


def _due(item):
    label = _text(item.get("dueLabel"))
    return " — " + label if label else ""


def run(scope):
    prepared = scope["prepared"]
    replies, actions = prepared["replies"], prepared["actions"]
    meetings = prepared["meetings"]
    today = datetime.date.fromisoformat(prepared["today"]).strftime("%m/%d")
    # The owner's knobs: which sections to write and how many priorities to pick; Java bounds both.
    sections = set(scope.get("sections") or ["priorities", "replies", "meetings", "actions"])
    count = int(scope.get("priority_count") or 5)
    lines = []
    if "priorities" in sections:
        lines.extend(["## Suggested priorities", ""])
        selected, seen = [], set()
        for item in sorted(replies + actions, key=_priority_key):
            key = item["key"]
            if key not in seen:
                selected.append(item)
                seen.add(key)
            if len(selected) == count:
                break
        for group, heading in (("today", "🔴 Due today, " + today), ("soon", "🟡 Due soon"),
                               ("flexible", "🟢 Flexible")):
            lines.extend(["### " + heading, ""])
            items = [item for item in selected if item.get("group") == group]
            lines.extend(["- " + _link(_title(item, "Review this item"), item.get("webLink")) + _due(item)
                          for item in items] or ["None selected."])
            lines.append("")

    if "replies" in sections:
        lines.extend(["## Needs your reply", ""])
        if not replies:
            lines.extend(["No new emails need a reply.", ""])
        for reply in replies:
            sender = _text(reply.get("from"))
            lines.extend(["**" + _link(_title(reply, "Reply needed"), reply.get("webLink")) + "**"
                          + (" — " + sender if sender else "") + _due(reply), ""])
            status = reply.get("draft")
            if status is None:
                # the owner turned reply drafts off
                continue
            if status == "saved":
                location = _text(reply.get("location"))
                draft = "Saved" + (" in " + location if location else "; location unavailable") + "; review before sending."
            elif status == "not written":
                draft = "No draft was written."
            elif status == "could not be saved":
                draft = "Draft could not be saved."
            else:
                draft = "Draft status unavailable."
            lines.extend(["- Draft: " + draft, ""])

    if "meetings" in sections:
        lines.extend(["## Today's meetings", ""])
        if meetings is None:
            lines.extend(["The calendar could not be read.", ""])
        elif not meetings:
            lines.extend(["The calendar is clear.", ""])
        else:
            notes = _meeting_notes(scope.get("meeting_notes"), len(meetings))
            for index, meeting in enumerate(meetings):
                time = "All day" if meeting.get("allDay") else "–".join(
                    _text(meeting.get(field)) for field in ("start", "end") if meeting.get(field))
                heading = _link(meeting.get("subject") or "Untitled meeting", meeting.get("webLink"))
                lines.extend(["### " + (time + " " if time else "") + heading, ""])
                note = notes.get(index)
                summary = note.get("summary") if note else None
                if _bounded(summary, 1200, 60, allow_empty=True):
                    brief = _text(summary) or "No additional context was identified."
                else:
                    brief = "Brief unavailable. Review the meeting invitation."
                lines.extend(["**Brief:** " + brief, ""])
                pre_reads = meeting.get("preReads") or []
                takeaways = {}
                if note and isinstance(note.get("preReads"), list):
                    for entry in note["preReads"]:
                        if not isinstance(entry, dict):
                            continue
                        number = _integer(entry.get("n"))
                        if number is not None and number > 0 and number not in takeaways and _bounded(entry.get("takeaway"), 800, 35):
                            takeaways[number] = entry["takeaway"]
                if pre_reads:
                    lines.extend(["**Pre-reads:**", ""])
                    for pre_read in pre_reads:
                        name = _link(pre_read.get("name") or "Unnamed attachment", pre_read.get("webLink"))
                        if not isinstance(pre_read.get("text"), str) or not pre_read["text"].strip():
                            detail = "Contents unavailable."
                        else:
                            detail = _text(takeaways.get(pre_read.get("n")))
                        lines.append("- " + name + (" — " + detail if detail else ""))
                    lines.append("")
                questions = note.get("questions") if note else None
                if isinstance(questions, list):
                    questions = list(dict.fromkeys(q for q in questions if _bounded(q, 350, 40)))[:3]
                    if questions:
                        lines.extend(["**Questions to ask:**", ""])
                        lines.extend("- " + _text(question) for question in questions)
                        lines.append("")

    if "actions" in sections:
        lines.extend(["## Open action items", ""])
        if not actions:
            lines.append("No open action items.")
        for action in actions:
            source = _text(action.get("thread") or action.get("from"))
            lines.append("- " + _link(_title(action, "Review this item"), action.get("webLink"))
                         + (" — " + source if source else "") + _due(action))
    return "\n".join(lines).rstrip() + "\n"
